import json,pathlib
root=pathlib.Path(__file__).resolve().parent.parent
B='https://www.brooklyn.edu/'
A=B+'admissions-aid/'
C='https://www.cuny.edu/admissions/undergraduate/'
items=[]
def add(id,title,pattern,body,url,source,question,group='Applying',review=False):
 items.append(dict(id=id,title=title,pattern=pattern,body=body,url=url,source=source,question=question,group=group,template='2020 Admissions Inquiry Templates',review=review,follow=['How can I contact admissions?','What are the application deadlines?']))
add('review','Understanding “under review”',r'\b(under review|being reviewed|application.*complete|complete.*application|missing.*document|incomplete|checklist)\b','An “under review” message is not an admission decision. Check your application details and any outstanding items in CUNYfirst to see whether documents are still requested.\n\nIf your application shows as complete, wait for the official decision or ask Admissions for an update. A complete application does not guarantee admission, and this guide cannot predict when your decision will arrive.\n\nI cannot access your application or verify receipt of documents.',C+'apply/','CUNY application and status guidance','What does under review mean?')
add('status','Check your application status',r'\b(application status|check.*status|status.*application|decision|denial|rejected|denied|hear back)\b','Log in to CUNYfirst using the account associated with your application and open your application details for Brooklyn College. Review the status, decision, and any outstanding requirements.\n\nFollow the instructions in your official decision notice. For an unclear status or a question about a decision, contact Undergraduate Admissions. I cannot view your records or tell you whether you were admitted.',C+'apply/','CUNY application status','How do I check my application status?')
add('late','If you missed an application deadline',r'\b(too late|late application|missed.*deadline|deadline.*missed|next semester|reapply)\b','Ask Admissions whether applications and outstanding documents are still being accepted for your intended term. CUNY says applications after a deadline may be considered where space remains.\n\nIf the term is closed, ask which application and documents are needed for a later term. Do not assume an earlier application or its documents will automatically carry forward. This guide cannot reopen an application or forward documents.',C+'apply/','CUNY application deadlines','Is it too late to complete my application?')
add('choice','Changing your college choice',r'\b(college choice|change.*college|reallocation|first choice)\b','If you want to change a CUNY college choice to Brooklyn College, ask Undergraduate Admissions for the current change-of-choice process and whether it is available for your intended term.\n\nThe supplied 2020 template mentions a form and a 15-business-day processing period. That turnaround has not been confirmed, so this guide does not promise it or claim your form has been received.',A+'first-year/','Undergraduate Admissions','How do I change my college choice?',review=True)
add('decline','Declining an admission offer',r'\b(decline|declining|reject.*offer|not attend|not attending|turn down)\b','If you decide not to attend, use the response instructions in your official admission offer or ask Admissions how to record your decision.\n\nA message in this chat does not decline your offer. If you already accepted, paid a deposit, or registered for classes, contact the appropriate college offices about the additional steps and any applicable deadlines.',A+'first-year/','Undergraduate Admissions','How do I decline my admission offer?','After admission',True)
add('deposit','Your commitment deposit',r'\b(deposit|commitment payment|commitment fee)\b','Follow your admission offer and CUNYfirst instructions to confirm whether a commitment deposit is required and how to pay it. Confirm the current amount and due date with Admissions before paying.\n\nCUNY’s new-student guide describes deposit waivers and recommends contacting your college if your financial situation has changed. I cannot determine your waiver eligibility or process a payment.', 'https://www.cuny.edu/admissions/new-students/','CUNY new-student deposit guidance','How do I pay the commitment deposit?','After admission')
add('accept','Accepting your admission offer',r'\b(accept.*offer|acceptance|accepted|admitted|admission offer|offer of admission)\b','If you have received an official offer, follow Brooklyn College’s Accept & Commit instructions and review the next steps for your student type. Complete any required commitment, account, and registration steps through the college’s systems.\n\nThis chat cannot accept your offer or confirm enrollment. Use your official offer for term-specific requirements.',B+'lp/first-year/commit/','Brooklyn College Accept & Commit','How do I accept my admission offer?','After admission')
add('summer','Summer courses before your first semester',r'\bsummer\b','If you have been admitted for a later term and want to start with summer courses, ask Admissions and an academic adviser whether your admission can support summer enrollment and which requirements you must complete first.\n\nConfirm prerequisites, course availability, tuition, financial aid, and how the courses fit your degree plan before registering. Acceptance for a later term alone does not confirm summer registration eligibility.',B+'lp/transfer/accept-commit-transfer/','Transfer student enrollment steps','Can admitted transfer students take summer classes?','After admission',True)
add('advisement','Plan your first semester with an adviser',r'\b(smart|advisement|orientation|registration|register for classes|academic advis[eo]r|schedule.*appointment|book.*appointment)\b','Use the current admitted-student checklist to arrange academic advisement and registration. Review your intended major, any transfer credit evaluation, and outstanding enrollment requirements with your adviser.\n\nThe 2020 document calls the appointment system “SMART.” Verify the current scheduling route through the college’s checklist rather than relying on those older screen-by-screen instructions.\n\nI can explain the next steps, but cannot book or confirm an appointment.',B+'lp/first-year/commit/','Advisement and enrollment checklist','How do I schedule a SMART or advisement appointment?','After admission')
add('webcentral','Set up your college accounts',r'\b(webcentral|web central|claim.*account|create.*account|activate.*account|cunyfirst|cuny first|login|log in|password)\b','Use the college’s current enrollment checklist to activate the accounts you need. CUNYfirst and Brooklyn College WebCentral are separate systems; follow the instructions for the account you are setting up.\n\nFor an account error, use the official support options linked by the college. Do not share your password, security answers, student ID, or verification codes in this chat.',B+'lp/transfer/accept-commit-transfer/','College account and enrollment steps','How do I activate WebCentral?','After admission')
add('declare','Confirm or declare your major',r'\b(declar.*major|confirm.*major|change.*major|major.*confirm|major.*declar)\b','Review your intended major with an academic adviser and use the college’s current instructions for declaring or confirming it. The major selected on an application may require additional steps after admission.\n\nFor transfer students, review how evaluated credits apply to the intended major in DegreeWorks before planning courses.',B+'lp/transfer/accept-commit-transfer/','Advisement and degree planning','How do I confirm my major?','After admission')
add('sat','SAT and ACT requirements',r'\b(sat|act|test.optional|1080|test scores|score report)\b','CUNY currently lists test-optional admissions through spring 2027. The 2020 template’s statement that SAT/ACT scores are required is outdated.\n\nFor a later entry term or a program with separate requirements, confirm the applicable policy with Admissions. Do not use the old template’s minimum scores as a current admission cutoff. If you choose to submit scores, follow the current CUNY submission instructions.',C,'CUNY undergraduate testing policy','Are SAT or ACT scores required?')
add('english','English proficiency scores and exemptions',r'\b(toefl|ielts|pte|duolingo|english proficiency|english.*exempt|exempt.*english|language.*waiver)\b','Ask Undergraduate Admissions which English proficiency tests, scores, and exemptions apply to your education history and intended entry term. Use the international applicant pathway for the current documentation instructions.\n\nThe supplied document contains a 2020 score-comparison table and exemption list. Those thresholds and exemptions have not been verified for current admission, so this preview does not use them to assess you. Do not assume an exemption based only on residency or immigration status.',A+'take-the-next-step/apply/','Current application pathways','What TOEFL, IELTS, or PTE score do I need?','International & English',True)
add('esl','English classes and adult literacy',r'\b(esl|esol|english classes|learn english|american language academy|ala|adult literacy|ged classes)\b','Brooklyn College’s Adult Literacy Program offers tuition-free ESOL and GED preparation for eligible New York State residents age 18 or older. The program lists a photo ID requirement and a waitlist.\n\nIts current page says it does not accept international students or process immigration documents, and directs international learners to CUNY English Language Institutes.\n\nThe old American Language Academy listing has not been confirmed; use the current Adult Literacy page for available options.',B+'literacy/','Adult Literacy Program','Does Brooklyn College offer ESL classes?','International & English')
add('graduate','Questions about graduate study',r'\b(graduate admissions?|graduate student|graduate program|graduate school|master|masters|phd|m\.a\.|m\.s\.)\b','For master’s programs or other graduate admissions questions, contact the Office of Graduate Admissions or the adviser for your intended program. Requirements vary by department.\n\nThe current graduate admissions page lists 222 West Quad Center and 718.951.4536. Use that page to explore programs and appointment options. I have not forwarded your inquiry.',A+'graduate/','Office of Graduate Admissions','Who can help with graduate admissions?','Other study options')
add('seek','Applying to SEEK as a transfer student',r'\b(seek|heop|eop|college discovery|special programs transfer)\b','Brooklyn College’s SEEK page explains how students transfer between opportunity programs. Submit the CUNY transfer application, then complete the Special Programs Transfer Request Form with your current campus.\n\nThe SEEK team must review your eligibility and required documentation. This guide cannot approve participation. Review the program’s own deadlines and orientation requirements on the linked page.',B+'seek/apply-to-seek/','Apply to SEEK','How do transfer students apply to SEEK?','Support programs')
add('asap','ASAP support at Brooklyn College',r'\b(asap|ace|accelerated study|accelerate complete)\b','Brooklyn College now has a CUNY ASAP program that supports bachelor’s-degree completion. The 2020 template’s statement that Brooklyn College does not offer ASAP is outdated.\n\nThe current program page lists full-time enrollment, eligible residency, approved majors, graduation timelines, and other requirements. It also states that students in SEEK or Macaulay Honors cannot participate in ASAP.\n\nReview the current eligibility page and contact the program team to learn whether you can join.',B+'cuny-asap/','Brooklyn College CUNY ASAP','Does Brooklyn College offer ASAP or ACE?','Support programs')
add('nondegree','Take courses without pursuing a degree',r'\b(non.degree|nondegree|nonmatriculated|personal enrichment)\b','An undergraduate nondegree student takes credit-bearing courses without pursuing a Brooklyn College degree. Apply through the official Nondegree Applicants page and submit its required documents.\n\nNondegree registration is space-available, and admission does not guarantee a seat in a class. The current page says nondegree students are not eligible for financial aid, scholarships, or grants.\n\nIf you are enrolled in a degree program at another college, review the visiting-student pathway instead.',A+'first-year/how-to-apply/non-degree-applicants/','Nondegree applicants','How do I apply as a non-degree student?','Other study options')
add('visiting','Take a course as a visiting student',r'\b(visiting student|e.?permit|another college.*course|non.cuny)\b','Students at a non-CUNY college can review Brooklyn College’s visiting-student application and transcript instructions. Visiting status is valid for one semester; a new application is required for each semester.\n\nStudents attending another CUNY college should consult their home college about an ePermit. Approval and course registration are separate steps. Confirm prerequisites and immunization requirements before registering.',A+'nontraditional/visiting-students/','Visiting students and ePermit','Can I attend as a visiting student?','Other study options')
add('waiver','Application fee waiver options',r'\b(fee waiver|waive.*fee|application fee|free application|application.*cost)\b','CUNY lists application fee waiver pathways, including qualifying current CUNY students, veterans and spouses, certain high school applicants, and economic-hardship applicants. The route and documentation depend on your circumstances.\n\nUse the current application-fee section on CUNY’s How to Apply page. A waiver request in this chat is not submitted or approved, and a tuition waiver is different from an application fee waiver.',C+'apply/','CUNY application fee waivers','Can I get an application fee waiver?','Costs & aid')
add('tuition','Understand your tuition and fees',r'\b(tuition|cost of attendance|per credit|semester cost|student fees|how much.*cost)\b','Tuition varies by New York residency, degree or nondegree status, and course load. Student fees and other costs may be additional.\n\nUse Brooklyn College’s current undergraduate tuition table to identify the applicable rate, and check the cost-of-attendance information for expenses such as books, housing, and transportation. The Bursar can explain your bill; this guide cannot calculate an official individual balance.',B+'bursar/tuition-and-fees/undergraduate/','Undergraduate tuition and fees','How much are undergraduate tuition and fees?','Costs & aid')
add('credit-evaluation','How your transfer credits are evaluated',r'\b(transfer.*credits?|transferring credits|credit.*transfer|credit evaluation|course equivalen|ap credit|ib credit|clep)\b','The Transfer Evaluations Office processes prior college and eligible exam credit for matriculated undergraduate students. Its page links to Transfer Explorer, evaluation tools, credit policies, and office support.\n\nAn equivalency preview is useful for planning, but it is not a final award of credit. Review your official evaluation and consult an adviser about how accepted credits fit your degree.',B+'teo/','Transfer Evaluations Office','How are my transfer credits evaluated?','Transfer students')
add('completion','How long will your degree take?',r'\b(how long.*degree|finish.*degree|degree.*finish|graduate in|two years|2 years|core curriculum|pathways|general education)\b','Your graduation timeline depends on accepted credits, remaining major and general education requirements, prerequisites, and the number of courses you can complete each term.\n\nReview your official credit evaluation and DegreeWorks audit with an adviser to make a semester-by-semester plan. The 2020 template’s two-year example and older Core Curriculum rules are not an individual graduation guarantee.',B+'lp/transfer/accept-commit-transfer/','Transfer advisement and degree planning','How long will it take to finish my degree after transferring?','Transfer students')
add('accreditation','High school diploma and accreditation questions',r'\b(accreditation|accredited|online high school|virtual high school|correspondence school|diploma.*accepted|homeschool|home school)\b','Ask CUNY Admissions to review the acceptability of your specific high school credential and tell you which supporting documents are required.\n\nThe 2020 document includes a staff-only accreditation list and broad statements about online schools. These have not been confirmed as current policy. This preview cannot approve or reject a diploma or tell you to obtain an equivalency credential based only on the type of school.',C+'apply/','CUNY document requirements','Will my high school diploma be accepted?',review=True)
(root/'dist/template-knowledge.js').write_text("'use strict';\n// Adapted from the user-supplied 2020 templates; current sources reviewed 2026-10-06.\nconst templateKnowledge = "+json.dumps(items,ensure_ascii=False,indent=2)+';\n')
print('Created',len(items),'template-based topics')
